from scipy.optimize import least_squares
F={'1':np.ones_like(x),'x':x,'v':v,'x2':x**2,'x3':x**3,'v2':v**2,'xv':x*v,'sinx':np.sin(x),'cosx':np.cos(x),'tx':t*x}
def fitlin(names):
    A=np.column_stack([F[n] for n in names])
    def resid(p):
        y=dv_dt-(p[0]*np.sin(p[1]*np.sqrt(v))+p[2]*np.exp(-p[3]*t**2)*v)
        c,_,_,_=np.linalg.lstsq(A,y,rcond=None)
        return A@c-y
    best=None
    for b0 in [2,3,4,5]:
        for d0 in [0.05,0.3,1]:
            r=least_squares(resid,[1,b0,1,d0])
            if best is None or r.cost<best.cost: best=r
    y=dv_dt-(best.x[0]*np.sin(best.x[1]*np.sqrt(v))+best.x[2]*np.exp(-best.x[3]*t**2)*v)
    c,_,_,_=np.linalg.lstsq(A,y,rcond=None)
    return np.round(best.x,4), np.round(c,4), round(best.cost*2/np.sum((dv_dt-dv_dt.mean())**2),6)
